#!/usr/bin/env bash
# The request body of connect-rust's log-ingest benchmark (bench/rpc, `log_request`, 50
# records) as binary protobuf, which the load generator sends to `rpc-server log` in the
# Connect protocol over HTTP/1.1. Generated by the load generator's script and checked.
# connect-rust's server is `rpc-server` of the bench workspace, which `benchrun build` builds
# per allocator; this directory holds only its input.
set -euo pipefail
dest="$1"
here=$(cd "$(dirname "$0")" && pwd)
python3 -I "$here/../../probes/loadgen/connect_log_body.py" 50 > "$dest/log50.bin"
echo "1155e384d3045bc3b872f197a58e406bb21579d61fbd827338cdf327adf58d4d  $dest/log50.bin" | sha256sum --check --quiet
